files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8892b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 520px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--accent);
  text-transform: uppercase;
}

.clock-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 100%;
}

#clockCanvas {
  width: 100%;
  max-width: 480px;
  height: auto;
  display: block;
  image-rendering: pixelated;
}

.ampm {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--muted);
  min-height: 1.5em;
}

.controls {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

.toggle-label {
  font-size: 1rem;
  color: var(--muted);
}

.toggle-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 24px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.2s, color 0.2s, transform 0.1s;
}

.toggle-btn:hover {
  background: var(--accent);
  color: var(--card);
}

.toggle-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.toggle-btn:active {
  transform: scale(0.96);
}

.toggle-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--card);
}

.lap-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  border-top: 1px solid var(--muted);
  padding-top: 16px;
  width: 100%;
}

.lap-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.lap-time {
  font-size: 1.75rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .title {
    font-size: 1.25rem;
  }
  .lap-time {
    font-size: 1.5rem;
  }
}

(function () {
  'use strict';

  var canvas = document.getElementById('clockCanvas');
  var ctx = canvas.getContext('2d');
  var ampmEl = document.getElementById('ampm');
  var toggleBtn = document.getElementById('formatToggle');
  var lapDisplay = document.getElementById('lapDisplay');

  var use24Hour = false;
  var pageOpenTime = Date.now();

  // 5x7 pixel font for digits 0-9 and colon
  var FONT = {
    '0': ['01110','10001','10011','10101','11001','10001','01110'],
    '1': ['00100','01100','00100','00100','00100','00100','01110'],
    '2': ['01110','10001','00001','00010','00100','01000','11111'],
    '3': ['11111','00010','00100','00010','00001','10001','01110'],
    '4': ['00010','00110','01010','10010','11111','00010','00010'],
    '5': ['11111','10000','11110','00001','00001','10001','01110'],
    '6': ['00110','01000','10000','11110','10001','10001','01110'],
    '7': ['11111','00001','00010','00100','01000','01000','01000'],
    '8': ['01110','10001','10001','01110','10001','10001','01110'],
    '9': ['01110','10001','10001','01111','00001','00010','01100'],
    ':': ['00000','00100','00100','00000','00100','00100','00000']
  };

  var PIXEL_SIZE = 10;
  var GAP = 2;
  var CHAR_GAP = 4;

  function drawChar(ch, x, y, color) {
    var pattern = FONT[ch];
    if (!pattern) return;
    ctx.fillStyle = color;
    for (var row = 0; row < pattern.length; row++) {
      for (var col = 0; col < pattern[row].length; col++) {
        if (pattern[row][col] === '1') {
          ctx.fillRect(x + col * (PIXEL_SIZE + GAP), y + row * (PIXEL_SIZE + GAP), PIXEL_SIZE, PIXEL_SIZE);
        }
      }
    }
  }

  function drawTime(timeStr, ampm) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var chars = timeStr.split('');
    var charWidth = 5 * (PIXEL_SIZE + GAP) - GAP;
    var totalWidth = chars.length * charWidth + (chars.length - 1) * CHAR_GAP;
    var startX = (canvas.width - totalWidth) / 2;
    var startY = (canvas.height - 7 * (PIXEL_SIZE + GAP) + GAP) / 2;

    for (var i = 0; i < chars.length; i++) {
      var x = startX + i * (charWidth + CHAR_GAP);
      drawChar(chars[i], x, startY, '#e94560');
    }

    ampmEl.textContent = ampm || '';
  }

  function pad(n) {
    return n < 10 ? '0' + n : '' + n;
  }

  function formatTime(date) {
    var h = date.getHours();
    var m = date.getMinutes();
    var s = date.getSeconds();
    var ampm = '';

    if (!use24Hour) {
      ampm = h >= 12 ? 'PM' : 'AM';
      h = h % 12;
      if (h === 0) h = 12;
    }

    return {
      text: pad(h) + ':' + pad(m) + ':' + pad(s),
      ampm: ampm
    };
  }

  function formatElapsed(ms) {
    var totalSec = Math.floor(ms / 1000);
    var h = Math.floor(totalSec / 3600);
    var m = Math.floor((totalSec % 3600) / 60);
    var s = totalSec % 60;
    return pad(h) + ':' + pad(m) + ':' + pad(s);
  }

  function tick() {
    var now = new Date();
    var formatted = formatTime(now);
    drawTime(formatted.text, formatted.ampm);
    lapDisplay.textContent = formatElapsed(Date.now() - pageOpenTime);
  }

  function scheduleTick() {
    tick();
    var now = Date.now();
    var delay = 1000 - (now % 1000);
    setTimeout(scheduleTick, delay);
  }

  toggleBtn.addEventListener('click', function () {
    use24Hour = !use24Hour;
    toggleBtn.setAttribute('aria-pressed', String(use24Hour));
    toggleBtn.textContent = use24Hour ? '24-hour' : '12-hour';
    tick();
  });

  // Initialize
  toggleBtn.textContent = '12-hour';
  scheduleTick();
})();
